from pathlib import Path

main_path = Path('app/src/main/java/com/clickgo/passageiro/MainActivity.java')
main = main_path.read_text(encoding='utf-8')

if 'import android.widget.ImageView;' not in main:
    main = main.replace('import android.widget.FrameLayout;\n', 'import android.widget.FrameLayout;\nimport android.widget.ImageView;\n', 1)
if 'import org.osmdroid.events.MapEventsReceiver;' not in main:
    main = main.replace('import org.osmdroid.util.BoundingBox;\n', 'import org.osmdroid.events.MapEventsReceiver;\nimport org.osmdroid.util.BoundingBox;\n', 1)
if 'import org.osmdroid.views.overlay.MapEventsOverlay;' not in main:
    main = main.replace('import org.osmdroid.views.overlay.Marker;\n', 'import org.osmdroid.views.overlay.MapEventsOverlay;\nimport org.osmdroid.views.overlay.Marker;\n', 1)

old_avatar = '''        TextView avatar = text("CG", 14, YELLOW, true);\n        avatar.setGravity(Gravity.CENTER);\n        avatar.setBackground(round(BLACK, 24, BLACK));\n        top.addView(avatar, new LinearLayout.LayoutParams(dp(48), dp(48)));\n'''
new_avatar = '''        ImageView avatar = new ImageView(this);\n        avatar.setImageDrawable(PassengerAvatar.circleDrawable(this));\n        avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);\n        top.addView(avatar, new LinearLayout.LayoutParams(dp(48), dp(48)));\n'''
