old_route = '''    private void drawRoute() {\n        if (map == null || origin == null || destination == null) return;\n        map.getOverlays().clear();\n        Marker start = new Marker(map);\n        start.setPosition(origin);\n        start.setTitle("Embarque");\n        start.setIcon(PassengerAvatar.markerDrawable(this));\n        start.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(start);\n        Marker end = new Marker(map);\n        end.setPosition(destination);\n        end.setTitle("Destino");\n        end.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(end);\n        Polyline line = new Polyline();\n        line.setPoints(Arrays.asList(origin, destination));\n        line.getOutlinePaint().setStrokeWidth(dp(6));\n        line.getOutlinePaint().setColor(Color.rgb(48, 92, 220));\n        map.getOverlays().add(line);\n        map.post(() -> {\n            if (map == null) return;\n            try {\n                BoundingBox box = BoundingBox.fromGeoPoints(Arrays.asList(origin, destination));\n                map.zoomToBoundingBox(box, true, dp(70));\n                map.invalidate();\n            } catch (Exception ignored) {}\n        });\n    }\n'''
new_route = '''    private void drawRoute() {\n        if (map == null || origin == null || destination == null) return;\n        drawRouteOverlays(Arrays.asList(origin, destination));\n        GeoPoint startPoint = new GeoPoint(origin.getLatitude(), origin.getLongitude());\n        GeoPoint endPoint = new GeoPoint(destination.getLatitude(), destination.getLongitude());\n        io.execute(() -> {\n            try {\n                String url = "https://router.project-osrm.org/route/v1/driving/"\n                        + startPoint.getLongitude() + "," + startPoint.getLatitude() + ";"\n                        + endPoint.getLongitude() + "," + endPoint.getLatitude()\n                        + "?overview=full&geometries=geojson&steps=false";\n                JSONObject root = new JSONObject(ApiClient.absoluteGet(url));\n                JSONArray routes = root.optJSONArray("routes");\n                if (routes == null || routes.length() == 0) return;\n                JSONObject geometry = routes.getJSONObject(0).optJSONObject("geometry");\n                JSONArray coords = geometry == null ? null : geometry.optJSONArray("coordinates");\n                if (coords == null || coords.length() < 2) return;\n                List<GeoPoint> roadPoints = new ArrayList<>();\n                for (int i = 0; i < coords.length(); i++) {\n                    JSONArray pair = coords.optJSONArray(i);\n                    if (pair == null || pair.length() < 2) continue;\n                    roadPoints.add(new GeoPoint(pair.optDouble(1), pair.optDouble(0)));\n                }\n                if (roadPoints.size() < 2) return;\n                ui.post(() -> { if (!destroyed && map != null) drawRouteOverlays(roadPoints); });\n            } catch (Exception ignored) { }\n        });\n    }\n\n    private void drawRouteOverlays(List<GeoPoint> routePoints) {\n        if (map == null || origin == null || destination == null) return;\n        map.getOverlays().clear();\n        Marker start = new Marker(map);\n        start.setPosition(origin);\n        start.setTitle("Embarque");\n        start.setIcon(PassengerAvatar.markerDrawable(this));\n        start.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(start);\n        Marker end = new Marker(map);\n        end.setPosition(destination);\n        end.setTitle("Destino");\n        end.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(end);\n        Polyline line = new Polyline();\n        line.setPoints(routePoints);\n        line.getOutlinePaint().setStrokeWidth(dp(6));\n        line.getOutlinePaint().setColor(Color.rgb(48, 92, 220));\n        map.getOverlays().add(line);\n        try { map.zoomToBoundingBox(BoundingBox.fromGeoPoints(routePoints), true, dp(70)); } catch (Exception ignored) {}\n        map.invalidate();\n    }\n\n    private void showMapPicker(boolean forOrigin, TextView originView) {\n        cancelAddressSearch();\n        LinearLayout root = vertical(Color.WHITE);\n        TextView title = text(forOrigin ? "Marque o local de embarque" : "Marque o destino", 20, BLACK, true);\n        title.setPadding(dp(16), dp(14), dp(16), dp(10));\n        root.addView(title, lpMatch(dp(58)));\n        FrameLayout frame = new FrameLayout(this);\n        MapView picker = new MapView(this);\n        picker.setTileSource(TileSourceFactory.MAPNIK);\n        picker.setMultiTouchControls(true);\n        GeoPoint initial = forOrigin ? origin : (destination != null ? destination : origin);\n        if (initial == null) initial = new GeoPoint(-14.52472, -49.14083);\n        picker.getController().setZoom(16.0);\n        picker.getController().setCenter(initial);\n        frame.addView(picker, new FrameLayout.LayoutParams(-1, -1));\n        Marker selected = new Marker(picker);\n        selected.setPosition(initial);\n        selected.setTitle(forOrigin ? "Embarque" : "Destino");\n        selected.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        picker.getOverlays().add(selected);\n        final GeoPoint[] chosen = { initial };\n        MapEventsOverlay events = new MapEventsOverlay(new MapEventsReceiver() {\n            @Override public boolean singleTapConfirmedHelper(GeoPoint point) {\n                chosen[0] = point;\n                selected.setPosition(point);\n                picker.invalidate();\n                return true;\n            }\n            @Override public boolean longPressHelper(GeoPoint point) { return singleTapConfirmedHelper(point); }\n        });\n        picker.getOverlays().add(0, events);\n        TextView tip = text("Toque no mapa para mover o marcador.", 13, Color.WHITE, true);\n        tip.setPadding(dp(12),0,dp(12),0); tip.setGravity(Gravity.CENTER); tip.setBackground(round(Color.argb(220,17,17,17),14,Color.TRANSPARENT));\n        FrameLayout.LayoutParams tipLp = new FrameLayout.LayoutParams(-2, dp(42)); tipLp.gravity = Gravity.TOP|Gravity.CENTER_HORIZONTAL; tipLp.topMargin = dp(14); frame.addView(tip, tipLp);\n        root.addView(frame, new LinearLayout.LayoutParams(-1, 0, 1));\n        LinearLayout actions = horizontal(); actions.setPadding(dp(14),dp(12),dp(14),dp(14));\n        Button back = secondaryLight("Voltar"); Button confirm = primary("Confirmar local");\n        actions.addView(back,new LinearLayout.LayoutParams(0,dp(56),1)); actions.addView(spaceH(8)); actions.addView(confirm,new LinearLayout.LayoutParams(0,dp(56),2)); root.addView(actions);\n        back.setOnClickListener(v -> { picker.onDetach(); showHome(); });\n        confirm.setOnClickListener(v -> {\n            GeoPoint point = chosen[0];\n            if (forOrigin) {\n                origin = point;\n                originLabel = "Local marcado no mapa";\n                if (originView != null) originView.setText(originLabel);\n                picker.onDetach();\n                showHome();\n            } else {\n                destination = point;\n                destinationLabel = "Destino marcado no mapa";\n                picker.onDetach();\n                showOptions();\n            }\n        });\n        setContentView(root);\n    }\n'''
if old_route not in main:
    raise SystemExit('Metodo drawRoute esperado nao encontrado')
main = main.replace(old_route, new_route, 1)
main_path.write_text(main, encoding='utf-8')

avatar_path = Path('app/src/main/java/com/clickgo/passageiro/PassengerAvatar.java')
avatar = avatar_path.read_text(encoding='utf-8')
needle = '''    public static String initials() {\n        return initials(fullName);\n    }\n'''
addition = '''    public static Drawable circleDrawable(Context context) {\n        float density = context.getResources().getDisplayMetrics().density;\n        int size = Math.max(48, Math.round(48 * density));\n        Bitmap output = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888);\n        Canvas canvas = new Canvas(output);\n        Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);\n        float cx = size / 2f;\n        float radius = size / 2f - Math.max(1f, density);\n        paint.setColor(Color.rgb(255, 212, 0));\n        canvas.drawCircle(cx, cx, radius, paint);\n        float inner = radius - Math.max(3f, 3f * density);\n        Bitmap currentPhoto = photo;\n        if (currentPhoto != null && !currentPhoto.isRecycled()) {\n            int save = canvas.save();\n            Path clip = new Path(); clip.addCircle(cx, cx, inner, Path.Direction.CW); canvas.clipPath(clip);\n            Rect src = centerCrop(currentPhoto); RectF dst = new RectF(cx-inner,cx-inner,cx+inner,cx+inner); canvas.drawBitmap(currentPhoto, src, dst, paint); canvas.restoreToCount(save);\n        } else {\n            paint.setColor(Color.rgb(17,17,17)); canvas.drawCircle(cx,cx,inner,paint);\n            paint.setColor(Color.rgb(255,212,0)); paint.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD)); paint.setTextAlign(Paint.Align.CENTER); paint.setTextSize(Math.max(14f,16f*density));\n            Paint.FontMetrics fm=paint.getFontMetrics(); canvas.drawText(initials(fullName),cx,cx-(fm.ascent+fm.descent)/2f,paint);\n        }\n        return new BitmapDrawable(context.getResources(), output);\n    }\n\n    public static String initials() {\n        return initials(fullName);\n    }\n'''
if needle not in avatar:
    raise SystemExit('Ponto de insercao do avatar circular nao encontrado')
avatar = avatar.replace(needle, addition, 1)
avatar_path.write_text(avatar, encoding='utf-8')

build_path = Path('app/build.gradle')
build = build_path.read_text(encoding='utf-8')
build = build.replace("versionCode 6", "versionCode 8", 1)
build = build.replace("versionName '0.6-native-beta'", "versionName '0.8-native-beta'", 1)
build_path.write_text(build, encoding='utf-8')

print('Passageiro v0.8: rota viaria, avatar e marcar no mapa aplicados.')